1328	// overkill; instead each CTA strides ALL bias outputs (cheap: ≤ 3d=384 rows × 9).
1329	// Single owner per output element (thread strides global bias-row index) → no atomics.
1330	__device__ __forceinline__ void dectc_dw_biases(
1331	        const DecDwSpec spec[9], float* __restrict__ grad) {
1332	    for (int s = 0; s < 9; ++s) {
1333	        const DecDwSpec& sp = spec[s];
1334	        for (int o = threadIdx.x; o < sp.Nout; o += blockDim.x) {
1335	            float accv = 0.0f;
1336	            for (int k = 0; k < sp.K; ++k) accv += __bfloat162float(sp.dY_bias[(int64_t)k * sp.Nout + o]);
1337	            grad[sp.bias_off + o] = accv;
1338	        }
1339	    }
