1343	//  P2 — EMBEDDING owner-scan (tok/pos). dh0 [T,d] (bf16) holds grad wrt h0.
1344	//    tok grad: row r (token id) of tok.weight → owner CTA (r % nCTA); the owner
1345	//    scans ALL T tokens in ascending t, accumulating dh0[t,:] for tokens whose
1346	//    id == r. pos grad: row p → owner; sums dh0[t,:] over t with (t%S)==p.
1347	//    Fixed t-order + single owner per row → deterministic, atomic-free.
1348	//    `tok_ids` is HBM int32 [T]. Writes grad[tok_off..], grad[pos_off..].
1349	// ════════════════════════════════════════════════════════════════════════
1350	__device__ __forceinline__ void dectc_embed_owner_scan(
1351	        const DecActs& acts, const int* __restrict__ tok_ids, int T,
1352	        float* __restrict__ grad, int cta, int nCTA) {
1353	    const int tok_off = kDecOffsets[0];   // tok.weight [V,d]
1354	    const int pos_off = kDecOffsets[1];   // pos.weight [S,d]
1355	    // tok rows owned by this CTA: r in [0,V) with r % nCTA == cta.
1356	    for (int r = cta; r < dec::kVocab; r += nCTA) {
1357	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1358	            float accv = 0.0f;
1359	            for (int t = 0; t < T; ++t)
1360	                if (tok_ids[t] == r) accv += __bfloat162float(acts.dh0[(int64_t)t * dec::kD + j]);
1361	            grad[tok_off + (int64_t)r * dec::kD + j] = accv;
1362	        }
1363	    }
1364	    // pos rows owned by this CTA: p in [0,S) with p % nCTA == cta.
1365	    for (int p = cta; p < dec::kSeq; p += nCTA) {
1366	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1367	            float accv = 0.0f;
1368	            for (int t = 0; t < T; ++t)
1369	                if ((t % dec::kSeq) == p) accv += __bfloat162float(acts.dh0[(int64_t)t * dec::kD + j]);
1370	            grad[pos_off + (int64_t)p * dec::kD + j] = accv;
1371	        }
1372	    }
1373	}
