679	    //    (supergrok11_sm90.cuh:246 / supergrok15_sm90.cuh:315). sharpness is then the
680	    //    2nd MLP input the P2.45 meta-net mu precompute reads. The SAM-step gate is the
681	    //    SAME st.looksam_sam host scalar (the SG sam_step cadence); on a non-SAM step
682	    //    the cached sharpness is reused verbatim. SG reuses st.rho as the perturbation
683	    //    radius (its own sam_rho), identical reduction/perturb math.
684	    if constexpr (Opt == OptId::LookSAM || Opt == OptId::SuperGrok11 ||
685	                  Opt == OptId::SuperGrok15 || Opt == OptId::SuperGrok2) {
686	        if (st.looksam_sam != 0.0f) {
687	            // (a) GLOBAL ‖g‖ over the reduced grad, deterministic (reuse the loss
688	            //     workspace as P2.5 does: loss_part[nCTA] = per-CTA Σg², loss_out[1]
689	            //     broadcasts rho_over_norm). The reduced loss is already in
690	            //     *tok.loss_out (host state), so this is free scratch.
691	            float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
692	            float* ron_bc  = loss_out;           // [1] broadcast rho_over_norm
693	            const int64_t total = kDecTotalElems;
694	            {
695	                const int64_t base = total / nCTA, rem = total % nCTA;
696	                const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
697	                const int64_t ecnt = base + (cta < rem ? 1 : 0);
698	                float tsum = 0.0f;
699	                for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
700	                    const float gv = grad[e0 + i];
701	                    tsum += gv * gv;
702	                }
703	                float* red = sm.red;
704	                red[threadIdx.x] = tsum;
705	                __syncthreads();
706	                for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
707	                    if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
708	                    __syncthreads();
709	                }
710	                if (threadIdx.x == 0) sq_part[cta] = red[0];
711	                bar.sync();   // B2.4a: all per-CTA Σg² partials complete
712	                if (cta == 0 && threadIdx.x == 0) {
713	                    double ss = 0.0;
714	                    for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
715	                    const float gnorm = sqrtf((float)ss);
716	                    // rho / ‖g‖ (matches bindings.cpp looksam_perturb_all). gnorm>0 in
717	                    // any real training step; guard div-by-0 → 0 (no perturb) to be safe.
718	                    *ron_bc = (gnorm > 0.0f) ? (st.rho / gnorm) : 0.0f;
719	                }
720	                bar.sync();   // B2.4b: rho_over_norm broadcast ready
721	            }
722	            const float rho_over_norm = *ron_bc;
723	            // (b) Backup + perturb p in place: p' = p + rho_over_norm·g. Grid-strided
724	            //     over the flat param vector (each element owned once → no race).
725	            {
726	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
727	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
728	                     i < total; i += gstride) {
729	                    sam_backup[i] = params[i];
730	                    params[i] = params[i] + rho_over_norm * grad[i];
731	                }
732	            }
733	            bar.sync();   // B2.4c: all params perturbed before the 2nd forward reads them
734	            // (c) SECOND fwd+bwd at the perturbed weights → g_sam in `sam_grad`. Mirror
735	            //     P1 + P2 EXACTLY, but: re-zero the lnvec partials (they accumulate),
736	            //     do NOT write the loss (keep the first-pass loss), and assemble into
737	            //     `sam_grad` (NOT `grad`). `w` wraps `params` (now perturbed) so the
738	            //     tile fns read the perturbed weights with no re-bind needed.
739	            for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
740	            bar.sync();   // B2.4d: lnvec partials cleared before the 2nd backward accumulates
741	            for (int ti = cta; ti < n_tiles; ti += nCTA) {
742	                const int g0 = ti * nrows_tile;
743	                const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
744	                dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
745	                                          sm.sA, sm.sB, sm.red);
746	                dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
747	                                           my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
748	                __syncthreads();
749	            }
750	            bar.sync();   // B2.4e: all 2nd-pass acts (X + dY) + LN-vec partials complete
751	            // Re-build the dW specs from the 2nd-pass acts (dY adjoints changed).
752	            if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
753	            __syncthreads();
754	            dectc::DecDwSpec* spec2 = sm.spec;
755	            const int n_dw2 = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec2);
756	            if (kDwG > 1) {
757	                for (int item = cta; item < n_dw2 * kDwG; item += nCTA) {
758	                    const int gt = item / kDwG, kc = item % kDwG;
759	                    dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec2, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
760	                }
761	                bar.sync();
762	                dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec2, n_dw2, kDwG, dw_part, sam_grad, cta, nCTA);
763	            } else {
764	                for (int gt = cta; gt < n_dw2; gt += nCTA)
765	                    dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec2, gt, sam_grad, sm.sA, sm.sB);
766	            }
767	            dectc::dectc_dw_biases(spec2, sam_grad);
768	            dectc::dectc_embed_owner_scan(acts, tok.tokens, T, sam_grad, cta, nCTA);
769	            dectc::dectc_lnvec_reduce(lnvec_base, sam_grad, nCTA, cta);
770	            bar.sync();   // B2.4f: g_sam fully assembled in sam_grad
771	            // (d) WRITE the SAM side-channel (into the persistent state slice) + restore p.
772	            //     LookSAM → sam_dir = g_sam − g; SuperGrok11/15/SuperGrok2 → sharpness =
773	            //     (g_sam − g)² (SG2 shares the SAM 2nd-backward machinery: its meta-net's
774	            //     2nd MLP input is the SAME sharpness signal, read by sg2_meta_stages).
775	            {
776	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
777	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
778	                     i < total; i += gstride) {
779	                    const float diff = sam_grad[i] - grad[i];
780	                    if constexpr (Opt == OptId::LookSAM) {
781	                        // st.sam_dir is the extra-slice base (host-bound). g_sam − g.
782	                        const_cast<float*>(st.sam_dir)[i] = diff;
783	                    } else {
784	                        // SuperGrok11/15/SuperGrok2: sharpness = (g_sam − g)² (state slice).
785	                        const_cast<float*>(st.sharpness)[i] = diff * diff;
786	                    }
787	                    params[i] = sam_backup[i];   // restore the ORIGINAL weights
788	                }
789	            }

