// ════════════════════════════════════════════════════════════════════════
__device__ void dectc_backward_tile(
        const DecWeights& w, int g0, int nrows, int B, const DecActs& acts,
        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
        float* __restrict__ lnvec, float* __restrict__ work2,
