// cost ever matters. tok_ids is HBM int32 [T].
__device__ __forceinline__ void dectc_embed_build_lists(
        const int* __restrict__ tok_ids, int T,
        int* __restrict__ row_start, int* __restrict__ perm) {
    __shared__ int cnt[dec::kVocab];
    // 1) zero the histogram (all threads).
    for (int r = threadIdx.x; r < dec::kVocab; r += blockDim.x) cnt[r] = 0;
    __syncthreads();
    // 2) histogram: count tokens per vocab row. Order-independent → smem atomics
    //    are exact (integer adds). All threads stride the T tokens.
    for (int t = threadIdx.x; t < T; t += blockDim.x) {
        const int r = tok_ids[t];
        if (r >= 0 && r < dec::kVocab) atomicAdd(&cnt[r], 1);
    }
    __syncthreads();
    // 3) exclusive prefix sum → row_start[V+1] (single thread; V tiny). row_start
    //    is also reused as the live scatter cursor in step 4, so stash the final
    //    total at [V] and rebuild cursors from a fresh exclusive scan.
    if (threadIdx.x == 0) {
        int acc = 0;
        for (int r = 0; r < dec::kVocab; ++r) { row_start[r] = acc; acc += cnt[r]; }
        row_start[dec::kVocab] = acc;   // == (#tokens with a valid row) ≤ T
        // 4) scatter ascending t → perm. cnt[] becomes the per-row running cursor
        //    (cnt[r] starts at row_start[r]); visiting t ascending + append makes
        //    each bucket ascending-t (the old scan's exact order).
        for (int r = 0; r < dec::kVocab; ++r) cnt[r] = row_start[r];
        for (int t = 0; t < T; ++t) {
            const int r = tok_ids[t];
            if (r >= 0 && r < dec::kVocab) perm[cnt[r]++] = t;
        }
    }
    __syncthreads();
}

